// 파일 책임: 기본 대화창 세 가지(Dialog·ConfirmDialog·AlertDialog)와 그 포커스 규칙.
// 열린 직후부터 닫힐 때까지 키보드 포커스가 창 밖으로 한 순간도 나가지 않게 한다(Base UI의 focus guard 경유를 막는다).
// 창·버튼 모양은 프로젝트의 shadcn Dialog·Button이 정하고, 여기서는 열림·닫기 정책·포커스·잠금 연결만 맡는다.
// 버튼 기본 문구(닫기·확인·취소·처리 중)와 확인 수명 창(ConfirmationDialog)의 실패·완료 문구는 앱 맨 위의 DialogDefaults 한 곳에서 받는다.
// 화면이 준 문구는 그 창에서만 앞선다.
import { Button } from '@/components/ui/button';
import {
  DialogClose,
  DialogContent,
  DialogFooter,
  Dialog as DialogRoot,
  DialogTitle,
} from '@/components/ui/dialog';
import type { useConfirmationState } from '@boosterlab/web-kit/dialog';
import {
  useAcknowledgeBinding,
  useConfirmBinding,
  useDialogBinding,
} from '@boosterlab/web-kit/dialog';
import { createContext, useContext, type ReactNode, type RefObject } from 'react';
import { Pending } from './pending';

/** 대화창 버튼의 앱 기본 문구. pending은 실행 중 진행 표시를 화면 낭독기가 읽는 문구다. */
export interface DialogLabels {
  readonly close: string;
  readonly confirm: string;
  readonly cancel: string;
  readonly pending: string;
}

/** 키트가 제공하는 한국어 문구. 한국어 앱은 이 값을 DialogDefaults에 그대로 넘긴다(공급이 없으면 한국어로 떨어지지 않고 오류가 난다). */
export const defaultDialogLabels: DialogLabels = {
  close: '닫기',
  confirm: '확인',
  cancel: '취소',
  pending: '처리 중입니다.',
};

/** 확인 수명 창(ConfirmationDialog)의 앱 기본 문구. 화면이 같은 이름의 값을 주면 그 창에서만 앞선다. */
export interface ConfirmationDefaults {
  /** 실행 실패(onError가 show로 돌려준 값)의 문구. */
  readonly renderFailure?: (failure: unknown) => ReactNode;
  /** 요청은 끝났고 후속 처리만 실패했을 때 본문 대신 보일 설명. */
  readonly completionMessage?: ReactNode;
  /** 그때 확인 버튼 문구(후속 처리만 다시 한다). */
  readonly retryLabel?: string;
}

const DialogLabelsContext = createContext<DialogLabels | undefined>(undefined);
const ConfirmationDefaultsContext = createContext<ConfirmationDefaults>({});

/**
 * 앱 맨 위에 한 번 두고 대화창 기본 문구 전체를 넘긴다. 이 아래의 Dialog·ConfirmDialog·AlertDialog(폼·목록이 그리는 창 포함)가 이 문구를 쓴다.
 * confirmation을 주면 이 아래 모든 ConfirmationDialog의 실패·완료 문구가 된다(화면마다 같은 값을 넘기지 않는다).
 * 폼 기본 문구(FormDefaults)와 따로 두어, 폼 없이 대화창만 설치한 앱도 이것만으로 쓴다.
 */
export function DialogDefaults({
  labels,
  confirmation = {},
  children,
}: {
  readonly labels: DialogLabels;
  readonly confirmation?: ConfirmationDefaults;
  readonly children: ReactNode;
}) {
  return (
    <DialogLabelsContext.Provider value={labels}>
      <ConfirmationDefaultsContext.Provider value={confirmation}>
        {children}
      </ConfirmationDefaultsContext.Provider>
    </DialogLabelsContext.Provider>
  );
}

/** 앱 기본 문구를 읽는다. 공급이 없으면 조용히 다른 언어로 그리지 않고 바로 오류로 알린다. */
function useDialogLabels(part: string): DialogLabels {
  const labels = useContext(DialogLabelsContext);
  if (labels === undefined) throw new Error(`<${part}> requires <DialogDefaults labels> above it`);
  return labels;
}

export interface DialogProps {
  readonly open: boolean;
  readonly title: ReactNode;
  readonly children?: ReactNode;
  /** 창 아래 버튼 자리. */
  readonly footer?: ReactNode;
  /** 닫기 요청(Esc·바깥 클릭·닫기 버튼). 판정은 호출자가 한다. */
  readonly onClose?: () => void;
  /** false면 Esc·바깥 클릭·닫기 버튼으로 닫히지 않는다(확인만 받는 알림, 실행 중). */
  readonly closable?: boolean;
  readonly closeLabel?: string;
  readonly role?: 'dialog' | 'alertdialog';
  /** 닫힌 뒤 포커스를 돌려줄 요소. 없으면 연 요소로 돌아간다. */
  readonly returnFocus?: RefObject<HTMLElement | null>;
  readonly className?: string;
}

/** 기본 대화창. 열리면 첫 입력·버튼에 바로 포커스하고 Tab 순환을 창 안에 가둔다. */
export function Dialog({
  open,
  title,
  children,
  footer,
  onClose,
  closable = true,
  closeLabel,
  role = 'dialog',
  returnFocus,
  className,
}: DialogProps) {
  const labels = useDialogLabels('Dialog');
  const { rootProps, popupRef, popupProps } = useDialogBinding({
    open,
    closable,
    onClose,
    returnFocus,
  });
  return (
    <DialogRoot {...rootProps}>
      {/* 닫기 버튼은 아래 버튼 자리 하나로만 둔다(shadcn 기본 모서리 닫기 버튼을 끈다). 첫 포커스 순서가 창 안 내용부터 시작한다. */}
      <DialogContent
        ref={popupRef}
        role={role}
        {...popupProps}
        showCloseButton={false}
        className={className}
        aria-describedby={undefined}
      >
        <DialogTitle>{title}</DialogTitle>
        {children === undefined ? null : (
          <div data-slot="dialog-body" className="grid gap-3">
            {children}
          </div>
        )}
        {footer === undefined && !closable ? null : (
          <DialogFooter className="items-center">
            {footer}
            {closable && footer === undefined ? (
              <DialogClose render={<Button variant="outline" />}>
                {closeLabel ?? labels.close}
              </DialogClose>
            ) : null}
          </DialogFooter>
        )}
      </DialogContent>
    </DialogRoot>
  );
}

function focusAcknowledgement(button: HTMLButtonElement | null) {
  button?.focus();
}

/** 실행 전 확인. 실행 중(pending)에는 닫기·재실행이 막히고 버튼 옆에 진행 표시가 선다. 승인·취소의 판정은 호출자가 한다. */
export function ConfirmDialog({
  open,
  title,
  children,
  confirmLabel,
  cancelLabel,
  onConfirm,
  onCancel,
  pending = false,
  pendingLabel,
  returnFocus,
  acknowledge = false,
}: {
  readonly open: boolean;
  readonly title: ReactNode;
  readonly children?: ReactNode;
  readonly confirmLabel?: string;
  readonly cancelLabel?: string;
  readonly onConfirm: () => void;
  readonly onCancel: () => void;
  readonly pending?: boolean;
  /** 실행 중 표시의 화면 낭독기 문구. */
  readonly pendingLabel?: string;
  readonly returnFocus?: RefObject<HTMLElement | null>;
  /** 같은 창에서 실행 결과를 확인한다. [확인]만 남고 닫기 요청은 막는다. */
  readonly acknowledge?: boolean;
}) {
  const labels = useDialogLabels('ConfirmDialog');
  const binding = useConfirmBinding({ pending, onConfirm, onCancel });
  return (
    <Dialog
      open={open}
      title={title}
      role="alertdialog"
      closable={!acknowledge && binding.closable}
      onClose={binding.cancel}
      returnFocus={returnFocus}
      footer={
        <>
          {!acknowledge && (
            <Button
              type="button"
              variant="outline"
              disabled={binding.locked}
              onClick={binding.cancel}
            >
              {cancelLabel ?? labels.cancel}
            </Button>
          )}
          <Button
            ref={acknowledge ? focusAcknowledgement : undefined}
            type="button"
            disabled={binding.locked}
            onClick={binding.confirm}
          >
            {acknowledge ? labels.confirm : (confirmLabel ?? labels.confirm)}
          </Button>
          {pending ? <Pending label={pendingLabel ?? labels.pending} /> : null}
        </>
      }
    >
      {children}
    </Dialog>
  );
}

/** 확인만 받는 알림(저장 완료 등). Esc·바깥 클릭으로 닫히지 않고, 확인을 연타해도 한 번만 알린다. */
export function AlertDialog({
  open,
  title,
  children,
  confirmLabel,
  onConfirm,
  pending = false,
  pendingLabel,
}: {
  readonly open: boolean;
  readonly title: ReactNode;
  readonly children?: ReactNode;
  readonly confirmLabel?: string;
  readonly onConfirm: () => void;
  /** 확인 뒤 할 일이 진행 중이면 true. 버튼이 잠기고 옆에 진행 표시가 선다. */
  readonly pending?: boolean;
  /** 진행 표시의 화면 낭독기 문구. */
  readonly pendingLabel?: string;
}) {
  const labels = useDialogLabels('AlertDialog');
  const binding = useAcknowledgeBinding({ open, pending, onConfirm });
  return (
    <Dialog
      open={open}
      title={title}
      role="alertdialog"
      closable={false}
      footer={
        <>
          {/* 잠금은 aria-disabled로 한다. disabled면 포커스가 창 밖으로 떨어진다. */}
          <Button type="button" aria-disabled={pending || undefined} onClick={binding.confirm}>
            {confirmLabel ?? labels.confirm}
          </Button>
          {pending ? <Pending label={pendingLabel ?? labels.pending} /> : null}
        </>
      }
    >
      {children}
    </Dialog>
  );
}

/**
 * 확인 수명의 표현 연결. 오류 분류·실행·대상 결정은 호출자가 소유한다.
 * 실패·완료 문구는 화면 값 → DialogDefaults confirmation 순으로 고른다. 실패 문구가 어디에도 없으면 바로 오류다.
 */
export function ConfirmationDialog<T, F>({
  confirmation,
  renderFailure: screenFailure,
  completionMessage: screenCompletion,
  retryLabel: screenRetry,
  ...props
}: {
  readonly confirmation: ReturnType<typeof useConfirmationState<T, F>>;
  /** 생략하면 DialogDefaults confirmation.renderFailure. */
  readonly renderFailure?: (failure: F) => ReactNode;
  /** 요청은 끝났고 후속 처리만 남았을 때의 설명과 재시도 버튼 문구. 생략하면 DialogDefaults confirmation의 값. */
  readonly completionMessage?: ReactNode;
  readonly retryLabel?: string;
} & Omit<Parameters<typeof ConfirmDialog>[0], 'open' | 'pending' | 'onConfirm' | 'onCancel'>) {
  const defaults = useContext(ConfirmationDefaultsContext);
  const renderFailure = screenFailure ?? defaults.renderFailure;
  if (renderFailure === undefined)
    throw new Error(
      '<ConfirmationDialog> requires renderFailure or <DialogDefaults confirmation> above it'
    );
  const completionMessage = screenCompletion ?? defaults.completionMessage;
  const retryLabel = screenRetry ?? defaults.retryLabel;
  const { state, covered, confirm, close } = confirmation;
  return (
    <ConfirmDialog
      {...props}
      confirmLabel={
        state.kind === 'open' && state.completed
          ? (retryLabel ?? props.confirmLabel)
          : props.confirmLabel
      }
      open={state.kind === 'open' && !covered}
      pending={state.kind === 'open' && state.pending}
      onConfirm={() => void confirm()}
      onCancel={close}
    >
      {state.kind === 'open' && state.completed && completionMessage !== undefined
        ? completionMessage
        : props.children}
      {state.kind === 'open' && state.failure !== undefined && (
        <p role="alert" className="text-destructive">
          {renderFailure(state.failure)}
        </p>
      )}
    </ConfirmDialog>
  );
}

// @vitest-environment jsdom
// 파일 책임: 설치한 dialog 복사본을 키트 공통 단위 검사에 연결한다.
import { ConfirmDialog, DialogDefaults, defaultDialogLabels } from '../dialog';
import { checkDialogConformance } from '@boosterlab/web-kit/testing/unit/primitives';
import installation from '../../../../../registry-installation.json';
checkDialogConformance(
  { ConfirmDialog, DialogDefaults, defaultDialogLabels },
  { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit }
);

// 아래는 이 복사본의 확인창 앱 기본값(DialogDefaults confirmation)과 화면별 덮어쓰기를 실제 useConfirmationState로 확인한다.
import { ConfirmationDialog } from '../dialog';
import { useConfirmationState } from '@boosterlab/web-kit/dialog';
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import type { ReactNode } from 'react';
import { afterEach, expect, it } from 'vitest';

afterEach(cleanup);

/** 실행이 실패하는 확인 하나와 열기 버튼. */
function FailingConfirmation({
  renderFailure,
}: {
  readonly renderFailure?: (failure: string) => ReactNode;
}) {
  const confirmation = useConfirmationState<number, string>({
    run: async () => {
      throw new Error('down');
    },
    onError: () => ({ kind: 'show', failure: 'down' }),
  });
  return (
    <>
      <button type="button" onClick={() => confirmation.request(1)}>
        open
      </button>
      <ConfirmationDialog confirmation={confirmation} title="Delete" renderFailure={renderFailure}>
        <p>body</p>
      </ConfirmationDialog>
    </>
  );
}

/** 실행은 성공하고 후속 처리만 실패하는 확인 하나. */
function CompletionFailingConfirmation() {
  const confirmation = useConfirmationState<number, string>({
    run: async () => 'done',
    onSuccess: async () => {
      throw new Error('navigation');
    },
    onError: () => ({ kind: 'show', failure: 'later' }),
  });
  return (
    <>
      <button type="button" onClick={() => confirmation.request(1)}>
        open
      </button>
      <ConfirmationDialog confirmation={confirmation} title="Delete">
        <p>body</p>
      </ConfirmationDialog>
    </>
  );
}

const withDefaults = (node: ReactNode) => (
  <DialogDefaults
    labels={defaultDialogLabels}
    confirmation={{
      renderFailure: (failure) => `APP FAILURE: ${String(failure)}`,
      completionMessage: <p>APP COMPLETION</p>,
      retryLabel: 'APP RETRY',
    }}
  >
    {node}
  </DialogDefaults>
);

it('shows the app confirmation failure copy when the screen gives none', async () => {
  render(withDefaults(<FailingConfirmation />));
  fireEvent.click(screen.getByText('open'));
  fireEvent.click(await screen.findByRole('button', { name: defaultDialogLabels.confirm }));
  expect(await screen.findByText('APP FAILURE: down')).toBeTruthy();
});

it('lets the screen failure copy win over the app default in that dialog only', async () => {
  render(withDefaults(<FailingConfirmation renderFailure={() => 'SCREEN FAILURE'} />));
  fireEvent.click(screen.getByText('open'));
  fireEvent.click(await screen.findByRole('button', { name: defaultDialogLabels.confirm }));
  expect(await screen.findByText('SCREEN FAILURE')).toBeTruthy();
  expect(screen.queryByText(/APP FAILURE/)).toBeNull();
});

it('shows the app completion message and retry label after only the follow-up failed', async () => {
  render(withDefaults(<CompletionFailingConfirmation />));
  fireEvent.click(screen.getByText('open'));
  fireEvent.click(await screen.findByRole('button', { name: defaultDialogLabels.confirm }));
  // 요청은 끝났고 후속 처리만 실패하면 창이 완료 설명과 재시도 버튼으로 남는다(요청은 다시 보내지 않는다).
  expect(await screen.findByText('APP COMPLETION')).toBeTruthy();
  expect(screen.getByRole('button', { name: 'APP RETRY' })).toBeTruthy();
  expect(screen.queryByText('body')).toBeNull();
});

it('fails loudly when neither the app nor the screen gives a failure renderer', () => {
  expect(() =>
    render(
      <DialogDefaults labels={defaultDialogLabels}>
        <FailingConfirmation />
      </DialogDefaults>
    )
  ).toThrow(
    '<ConfirmationDialog> requires renderFailure or <DialogDefaults confirmation> above it'
  );
});

// 파일 책임: 소비 복사본을 키트의 브라우저 검사 화면에 전달한다.
import { useState } from 'react';
import { createRoot } from 'react-dom/client';
import { createDialogConformancePage } from '@boosterlab/web-kit/testing/fixtures/dialog';
import { ConfirmDialog, Dialog, DialogDefaults, defaultDialogLabels } from '../dialog';
// 프로젝트 테마 CSS(components.json의 tailwind.css = src/styles.css)로 실제 화면과 같은 층·모양에서 검사한다. 위치가 다르면 이 import를 고친다.
import '@/styles.css';
const Page = createDialogConformancePage({ Dialog, DialogDefaults, defaultDialogLabels });
function ResultDialogExample() {
  const [phase, setPhase] = useState<'closed' | 'confirm' | 'running' | 'result'>('closed');
  return (
    <DialogDefaults labels={defaultDialogLabels}>
      <button type="button" onClick={() => setPhase('confirm')}>
        Start bulk action
      </button>
      <ConfirmDialog
        open={phase !== 'closed'}
        title={phase === 'result' ? 'Bulk action results' : 'Apply to selected rows?'}
        pending={phase === 'running'}
        acknowledge={phase === 'result'}
        onCancel={() => setPhase('closed')}
        onConfirm={() => {
          if (phase === 'result') setPhase('closed');
          else {
            setPhase('running');
            window.setTimeout(() => setPhase('result'), 60);
          }
        }}
      >
        {phase === 'result' ? <p>1 processed · 1 not processed</p> : null}
      </ConfirmDialog>
    </DialogDefaults>
  );
}

createRoot(document.getElementById('root')!).render(
  <>
    <Page />
    <ResultDialogExample />
  </>
);

import { expect, test } from '@playwright/test';
// 파일 책임: 설치한 브라우저 검사 화면을 키트 Playwright 적합성 검사에 연결한다.
import { checkDialogBrowser } from '@boosterlab/web-kit/testing/browser';
import installation from '../../../registry-installation.json' with { type: 'json' };
checkDialogBrowser({
  url: '/web-kit-checks/dialog.html',
  target: { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit },
});

test('hands keyboard focus from the running confirmation to its result and back', async ({
  page,
}) => {
  await page.goto('/web-kit-checks/dialog.html');
  const start = page.getByRole('button', { name: 'Start bulk action' });
  await start.focus();
  await page.keyboard.press('Enter');
  const confirm = page.getByRole('alertdialog', { name: 'Apply to selected rows?' });
  await expect(confirm).toBeVisible();
  await confirm.getByRole('button', { name: '확인' }).press('Enter');

  const result = page.getByRole('alertdialog', { name: 'Bulk action results' });
  await expect(page.getByRole('alertdialog')).toHaveCount(1);
  await expect(result.getByText('1 processed · 1 not processed')).toBeVisible();
  const acknowledge = result.getByRole('button', { name: '확인' });
  await expect(acknowledge).toBeFocused();
  await page.keyboard.press('Escape');
  await expect(result).toBeVisible();
  await page.keyboard.press('Tab');
  await expect(acknowledge).toBeFocused();
  await page.keyboard.press('Enter');
  await expect(result).toBeHidden();
  await expect(start).toBeFocused();
});
